\maketitle

\begin{abstract}
Expander graphs and high-girth graphs are two of the most fertile structural
ideas in combinatorics and coding theory, and folklore has long linked them:
graphs that ``look locally like trees'' (high girth) tend to spread small sets
well (good expansion). We make this link precise in the extremal regime,
modeling a left-$d$-regular bipartite graph by a neighbor function
$N : L \to \mathrm{Finset}\,R$ with $|N(u)| = d$ for all $u$. We study the
conjectured equivalence
\[
\text{$N$ is an $s$-optimal small-set expander} \iff \girth(N) \ge 2s+2,
\]
where \emph{$s$-optimal small-set expander} means $|N(X)| = d\,|X|$ for every
left set $X$ with $|X| \le s$, and girth is measured combinatorially through
the absence of $2k$-cycles for $2 \le k \le s$. Our findings: (1) the forward
implication is true in full generality (\code{optimal\_imp\_girth}); (2) the
converse is false for every $s \ge 2$, witnessed by an explicit $3$-vertex
counterexample (\code{converse\_false}); and (3) the failed converse is
replaced by two exact characterizations: optimal expansion equals
pairwise-disjoint neighborhoods for all $s \ge 2$ (\code{optimal\_iff\_disjoint}),
and girth $\ge 6$ equals every two left vertices sharing at most one neighbor
(\code{no\_four\_cycle\_iff}). The diagnostic heart is a cycle-extraction lemma
(\code{cycle\_shared\_neighbor}). The corrected picture exposes a precise
exchange rate: high girth controls overlap \emph{multiplicity}, while optimal
expansion controls overlap \emph{existence}, the latter strictly stronger and
equivalent to a vertex-disjoint union of stars.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
A bipartite graph between a left vertex set $L$ and a right vertex set $R$
models many objects in theoretical computer science: the Tanner graph of a
linear code, a hypergraph incidence structure, or a sampler. When the graph is
\emph{left-regular} of degree $d$, the central quality measure is
\emph{expansion}: the rate at which the neighborhood
$N(X) = \bigcup_{u\in X} N(u)$ grows with $|X|$. The strongest form is
\emph{optimal small-set expansion}, where $|N(X)|$ attains its maximum
$d\,|X|$ for all small $X$. A second measure is \emph{girth}, the length of the
shortest cycle. Both are ``tree-like'' virtues, and folklore treats them as
nearly interchangeable; LDPC and expander codes are designed for high girth
partly because it is believed to promote expansion.

\subsection{The proposed bridge}
\begin{conjecture}[naive bridge]
A left-$d$-regular bipartite graph $N$ is an $s$-optimal small-set expander if
and only if its girth is at least $2s+2$.
\end{conjecture}
We confirm one direction, refute the other with an explicit construction, and
replace the broken equivalence with two provable characterizations.

\subsection{Contributions}
\begin{enumerate}
  \item \textbf{Forward bridge (true).} \code{optimal\_imp\_girth}: optimal
  expansion $\Rightarrow$ girth $\ge 2s+2$, for general $s$.
  \item \textbf{Counterexample.} \code{converse\_false}: an explicit
  left-$2$-regular graph with girth $\ge 6$ that is not $2$-optimal.
  \item \textbf{Disjointness characterization.} \code{optimal\_iff\_disjoint}:
  for $s \ge 2$, optimal $\iff$ pairwise-disjoint; hence $s$ collapses to $2$.
  \item \textbf{Girth-$6$ characterization.} \code{no\_four\_cycle\_iff}: no
  $4$-cycle $\iff$ every two left vertices share at most one neighbor.
  \item \textbf{Structural pivot.} \code{cycle\_shared\_neighbor} and
  \code{disjoint\_imp\_no\_cycle}.
\end{enumerate}

\section{The model and definitions}
Throughout, $L$ and $R$ are types with decidable equality, and
$N : L \to \mathrm{Finset}\,R$ is a \emph{neighbor function}.

\begin{definition}[Neighborhood]
For finite $X \subseteq L$, $\;N(X) := \bigcup_{u \in X} N(u)$ \quad(\code{nbhd}).
\end{definition}

\begin{definition}[Left-regularity]
$N$ is \emph{left-$d$-regular} if $|N(u)| = d$ for all $u$ (\code{LeftRegular}).
\end{definition}

\begin{definition}[$s$-optimal small-set expander]
$N$ is an \emph{$s$-optimal small-set expander} if $|N(X)| = d\,|X|$ for all
$X$ with $|X| \le s$ (\code{OptimalExpander}). The bound $|N(X)| \le d\,|X|$
always holds; optimality is its saturation.
\end{definition}

\begin{definition}[Combinatorial $2k$-cycle]
$N$ \emph{has a $2k$-cycle} (\code{HasCycle N k}) if there are injections
$u : \mathbb{Z}/k \to L$ and $w : \mathbb{Z}/k \to R$ with, for all $i$,
$w_i \in N(u_i)$ and $w_i \in N(u_{\sigma(i)})$, where $\sigma$ is the cyclic
successor on $\mathbb{Z}/k$. The $k$ distinct left and $k$ distinct right
vertices form a closed ring of length $2k$.
\end{definition}

\begin{definition}[Short cycle, girth]
$N$ has a short cycle relative to $s$ if some $k$ with $2 \le k \le s$ admits a
$2k$-cycle (\code{HasShortCycle}). $N$ has \emph{girth $\ge 2s+2$}
(\code{GirthGe}) if it has no short cycle; equivalently no cycle of length in
$\{4,6,\dots,2s\}$.
\end{definition}

\begin{definition}[Pairwise disjointness]
$N$ has \emph{all pairs disjoint} (\code{AllPairsDisjoint}) if
$u \ne v \Rightarrow N(u) \cap N(v) = \varnothing$; such a graph is a
vertex-disjoint union of stars.
\end{definition}

\begin{remark}[the smallest cycle]\label{rem:fourcycle}
For $k=2$, $\sigma$ swaps the two indices, so a $4$-cycle is precisely a pair
$u_0 \ne u_1$ together with two distinct $w_0 \ne w_1 \in N(u_0)\cap N(u_1)$.
Thus ``$N$ has a $4$-cycle'' $\iff$ ``some two left vertices share at least two
neighbors.''
\end{remark}

\section{Foundational lemmas}

\begin{lemma}[Monotonicity, \code{nbhd\_card\_mono}]
If $X \subseteq Y$ then $|N(X)| \le |N(Y)|$.
\end{lemma}
\begin{proof}[Proof sketch]
$N(X) \subseteq N(Y)$ by monotonicity of the indexed union, and cardinality is
monotone under inclusion.
\end{proof}

\begin{lemma}[Cycle extraction, \code{cycle\_shared\_neighbor}]\label{lem:extract}
If $k \ge 2$ and $N$ has a $2k$-cycle, there exist $a \ne b$ in $L$ with
$N(a) \cap N(b) \ne \varnothing$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $k = m+2$, take cycle data $(u,w)$, and set $a = u_0$, $b = u_1$.
Injectivity of $u$ gives $a \ne b$. The cycle condition at $i=0$ gives
$w_0 \in N(u_0) \cap N(u_1) = N(a) \cap N(b)$.
\end{proof}

\begin{lemma}[Disjointness kills cycles, \code{disjoint\_imp\_no\_cycle}]\label{lem:disjnocyc}
If $N$ has all pairs disjoint and $k \ge 2$, then $N$ has no $2k$-cycle; a
disjoint union of stars has infinite girth.
\end{lemma}
\begin{proof}[Proof sketch]
A $2k$-cycle would yield, via Lemma~\ref{lem:extract}, $a \ne b$ with
$N(a) \cap N(b) \ne \varnothing$, contradicting disjointness.
\end{proof}

\section{The forward bridge (true)}

\begin{theorem}[\code{optimal\_imp\_girth}]\label{thm:forward}
Let $N$ be left-$d$-regular. If $N$ is an $s$-optimal small-set expander, then
$\girth(N) \ge 2s+2$.
\end{theorem}
\begin{proof}[Proof sketch]
Suppose a short cycle exists: $2 \le k \le s$ and a $2k$-cycle; then $2 \le s$.
For $u \ne v$ apply optimality to $X = \{u,v\}$:
$|N(u) \cup N(v)| = 2d$. Inclusion--exclusion with left-regularity gives
$|N(u)\cup N(v)| + |N(u)\cap N(v)| = 2d$, hence $|N(u)\cap N(v)| = 0$. So $N$
has all pairs disjoint. By Lemma~\ref{lem:disjnocyc} there is no $2k$-cycle, a
contradiction. Therefore $\girth(N) \ge 2s+2$.
\end{proof}

\begin{remark}
The proof shows optimality forces \emph{global} disjointness, from which the
girth bound follows; this over-supply is exactly why the converse fails.
\end{remark}

\section{The converse fails}

\begin{theorem}[\code{converse\_false}]\label{thm:cex}
There is a left-$2$-regular bipartite graph with $\girth \ge 6$ (i.e.
\code{GirthGe N 2}) that is not a $2$-optimal small-set expander.
\end{theorem}
\begin{proof}[Construction and proof sketch]
Let $L = \{0,1\}$, $R = \{0,1,2\}$, $d=2$, $N(0) = \{0,1\}$, $N(1) = \{1,2\}$.
Each left vertex has $2$ neighbors. By Remark~\ref{rem:fourcycle} a $4$-cycle
needs two shared neighbors, but $N(0)\cap N(1) = \{1\}$; with two left vertices
no longer cycle exists, so $\girth \ge 6$. Yet
$N(\{0,1\}) = \{0,1,2\}$ has size $3 \ne 4 = d\cdot 2$, so optimality fails.
\end{proof}

\noindent\textbf{Diagnosis.} A single shared neighbor is a collision, not a
cycle: girth ignores it, optimality forbids it. Girth forbids closed loops;
optimal expansion forbids all overlap, which is strictly stronger.

\section{The correct replacements}

\begin{theorem}[Girth-$6$ characterization, \code{no\_four\_cycle\_iff}]
$N$ has no $4$-cycle (i.e. $\girth \ge 6$) iff every two distinct left vertices
share at most one neighbor: $\neg\code{HasCycle}(N,2) \iff (\forall u\ne v,\
|N(u)\cap N(v)| \le 1)$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) If $u \ne v$ share $w_0 \ne w_1$, the data $(u_0,u_1)=(u,v)$,
$(w_0,w_1)$ form a $4$-cycle. ($\Leftarrow$) A $4$-cycle gives, by
Remark~\ref{rem:fourcycle}, two distinct common neighbors of some pair.
\end{proof}

\begin{theorem}[Optimal $\equiv$ disjoint, \code{optimal\_iff\_disjoint}]\label{thm:optdisj}
For every $s \ge 2$, $N$ is an $s$-optimal small-set expander iff $N$ has all
pairs disjoint.
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) As in Theorem~\ref{thm:forward}, optimality on $\{u,v\}$ with
inclusion--exclusion forces $N(u)\cap N(v) = \varnothing$. ($\Leftarrow$) If
all pairs are disjoint and $|X| \le s$, then $\{N(u)\}_{u\in X}$ is pairwise
disjoint, so $|N(X)| = \sum_{u\in X}|N(u)| = d|X|$.
\end{proof}

\begin{corollary}[Threshold collapse]
For all $s \ge 2$,
$\code{OptimalExpander}(N,d,s) \iff \code{OptimalExpander}(N,d,2) \iff
\code{AllPairsDisjoint}(N)$. Optimal small-set expansion is purely pairwise.
\end{corollary}

\begin{corollary}[Strictness]
Optimal expansion implies but is not implied by girth $\ge 2s+2$: by
Lemma~\ref{lem:disjnocyc} an optimal expander has infinite girth, while
Theorem~\ref{thm:cex} gives a finite-girth-clearing non-optimal graph.
\end{corollary}

\section{The exchange rate between girth and expansion}

\begin{center}
\begin{tabular}{lll}
\toprule
Property & Forbids & Local meaning \\
\midrule
No $4$-cycle (girth $\ge 6$) & sharing \emph{two} neighbors & every pair shares $\le 1$ \\
Optimal expansion ($s\ge 2$) & sharing \emph{any} neighbor & every pair shares $0$ \\
\bottomrule
\end{tabular}
\end{center}

\noindent The naive conjecture conflated ``share at most one'' with ``share
none.'' That one-vertex gap --- invisible to cycles, fatal to optimality --- is
why the equivalence is one-directional. Optimal expansion is the infinite-girth
extreme (disjoint stars), strictly inside the finite-girth condition.

\section{Algorithms}
All procedures run in time polynomial in $|L|,|R|,d$.

\paragraph{Optimal-expander test via disjointness (Thm.~\ref{thm:optdisj}).}
Check every pair $\{u,v\}$ for $N(u)\cap N(v) \ne \varnothing$; complexity
$O(|L|^2 d)$, independent of $s$.

\paragraph{Girth-$\ge 6$ test.} Check every pair for
$|N(u)\cap N(v)| \ge 2$; complexity $O(|L|^2 d)$.

\paragraph{Direct optimality check.} Compute $N(X)$ and compare $|N(X)|$ with
$d|X|$; used to certify Theorem~\ref{thm:cex}.

\section{Applications and discussion}
For Tanner graphs of LDPC/expander codes, the girth-$6$ test gives an
$O(|L|^2 d)$ certificate, and the exchange table clarifies what it guarantees
(bounded overlap) and not (zero overlap). Optimal small-set expansion is a
disjoint packing of stars, verifiable in quadratic time regardless of $s$.
A subtle point: optimality is parameter-free beyond $s=2$, whereas girth is
genuinely $s$-parameterized; this asymmetry alone precludes equivalence.

\section{Future directions}

\begin{conjecture}[C1: Forest characterization]
$\code{GirthGe}(N,s)$ holds iff every set $X$ of $\le s$ left vertices induces
an acyclic subgraph on $X \cup N(X)$. A $2k$-cycle lives inside the subgraph
induced by its $k$ left vertices, so forbidding short cycles is forbidding
induced cycles on small left-sets; the pivot \code{cycle\_shared\_neighbor} and
model \code{HasCycle} are in hand, needing a \code{SimpleGraph.IsAcyclic} bridge.
\end{conjecture}

\begin{conjecture}[C2: Quantitative floor]
If $\code{GirthGe}(N,s)$ then $|X|\le s$ implies $(d-1)|X| + 1 \le |N(X)|$,
tight for a single tree component, by an induced-forest edge count; the upper
bound $|N(X)| \le d|X|$ is available via \code{nbhd\_card\_mono}.
\end{conjecture}

\begin{conjecture}[C3: Threshold collapse]
For $s \ge 2$, $\code{OptimalExpander}(N,d,s)$ is independent of $s$; this is
recorded as the collapse corollary, with \code{optimal\_iff\_disjoint} supplying
both endpoints.
\end{conjecture}

\begin{conjecture}[C4: Unique-neighbor refinement]
The correct coding-theoretic analogue: $\girth \ge 2s+2$ iff every $X$ with
$|X|\le s$ has a unique-neighbor vertex, connecting girth to the
Spielman--Tanner analysis of expander codes $B(G)$.
\end{conjecture}

\section{Conclusion}
The literal girth--expansion bridge is one-directional:
\code{optimal\_imp\_girth} holds for general $s$, but the converse fails
(\code{converse\_false}) because exactly $d|X|$ neighbors forces
pairwise-disjoint neighborhoods (\code{optimal\_iff\_disjoint}), strictly
stronger than excluding short cycles. The genuine girth-$6$ statement is
\code{no\_four\_cycle\_iff}. Together these convert a plausible but false
equivalence into an exact account of how reach and loops relate.

